/* Enforce hidden attribute precedence */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c1a27;
  --color-surface: #2b283e;
  --color-surface-hover: #37334f;
  --color-border: #4d466f;
  --color-accent: #f8c058;
  --color-accent-hover: #ffd685;
  --color-success: #55c57a;
  --color-text-main: #f5f4fa;
  --color-text-muted: #aca5cd;
  --focus-ring: 3px solid #f8c058;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  padding: 24px 16px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
}

.shelter-container {
  width: 100%;
  max-width: 840px;
  background: var(--color-surface);
  border: 4px solid var(--color-border);
  box-shadow: 0 8px 0 rgba(0, 0, 0, 0.4);
  border-radius: 8px;
  padding: 32px 24px;
}

.shelter-header {
  text-align: center;
  margin-bottom: 28px;
}

.shelter-logo {
  width: 16px;
  height: 16px;
  margin: 0 auto 12px;
  box-shadow:
    -6px 0 0 0 #f8c058,
    6px 0 0 0 #f8c058,
    -4px -4px 0 0 #f8c058,
    4px -4px 0 0 #f8c058,
    0 2px 0 0 #f8c058,
    -4px 4px 0 0 #f8c058,
    4px 4px 0 0 #f8c058,
    0 6px 0 0 #f8c058;
}

.shelter-title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--color-accent);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.shelter-subtitle {
  color: var(--color-text-muted);
  font-size: 1rem;
}

.status-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  background: rgba(0, 0, 0, 0.25);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  padding: 16px 20px;
  justify-content: space-around;
  margin-bottom: 28px;
}

.stat-box {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stat-label {
  font-size: 1.05rem;
  color: var(--color-text-muted);
}

.stat-value {
  font-size: 1.5rem;
  color: var(--color-accent);
  min-width: 2ch;
}

.filters-section {
  margin-bottom: 28px;
}

.section-label {
  font-size: 1rem;
  color: var(--color-text-muted);
  margin-bottom: 12px;
}

.filter-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.filter-btn {
  background: var(--color-surface);
  color: var(--color-text-main);
  border: 2px solid var(--color-border);
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 4px;
  transition: background 0.15s ease, border-color 0.15s ease;
}

.filter-btn:hover {
  background: var(--color-surface-hover);
  border-color: var(--color-accent);
}

.filter-btn:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.filter-btn.active {
  background: var(--color-accent);
  color: #121019;
  border-color: var(--color-accent);
}

.section-heading {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-accent);
  border-bottom: 2px dashed var(--color-border);
  padding-bottom: 8px;
  margin-bottom: 20px;
}

.pets-section,
.adopted-section {
  margin-bottom: 32px;
}

.pet-grid,
.adopted-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 16px;
}

.pet-card {
  background: var(--color-surface-hover);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transition: transform 0.15s ease, border-color 0.15s ease;
}

.pet-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-2px);
}

.pet-card.adopted {
  border-color: var(--color-success);
  background: rgba(85, 197, 122, 0.08);
}

.sprite-box {
  width: 64px;
  height: 64px;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.25);
  border: 2px solid var(--color-border);
  border-radius: 4px;
}

/* Pure CSS pixel art graphics */
.pixel-sprite {
  width: 4px;
  height: 4px;
}

.pixel-cat {
  box-shadow:
    /* ears */
    -8px -12px 0 0 #f8c058, 8px -12px 0 0 #f8c058,
    -4px -8px 0 0 #f8c058, 4px -8px 0 0 #f8c058,
    /* head */
    -8px -4px 0 0 #f8c058, -4px -4px 0 0 #f8c058, 0px -4px 0 0 #f8c058, 4px -4px 0 0 #f8c058, 8px -4px 0 0 #f8c058,
    /* eyes */
    -8px 0 0 0 #f8c058, -4px 0 0 0 #1c1a27, 0px 0 0 0 #f8c058, 4px 0 0 0 #1c1a27, 8px 0 0 0 #f8c058,
    /* nose & mouth */
    -8px 4px 0 0 #f8c058, -4px 4px 0 0 #f8c058, 0px 4px 0 0 #e87b7b, 4px 4px 0 0 #f8c058, 8px 4px 0 0 #f8c058,
    /* body */
    -8px 8px 0 0 #f8c058, -4px 8px 0 0 #f8c058, 0px 8px 0 0 #f8c058, 4px 8px 0 0 #f8c058, 8px 8px 0 0 #f8c058,
    -4px 12px 0 0 #f8c058, 4px 12px 0 0 #f8c058;
}

.pixel-dog {
  box-shadow:
    /* ears */
    -12px -8px 0 0 #a9754f, 12px -8px 0 0 #a9754f,
    -12px -4px 0 0 #a9754f, 12px -4px 0 0 #a9754f,
    /* head */
    -8px -8px 0 0 #d99f6b, -4px -8px 0 0 #d99f6b, 0px -8px 0 0 #d99f6b, 4px -8px 0 0 #d99f6b, 8px -8px 0 0 #d99f6b,
    -8px -4px 0 0 #d99f6b, -4px -4px 0 0 #1c1a27, 0px -4px 0 0 #d99f6b, 4px -4px 0 0 #1c1a27, 8px -4px 0 0 #d99f6b,
    /* muzzle */
    -4px 0 0 0 #f5f4fa, 0px 0 0 0 #1c1a27, 4px 0 0 0 #f5f4fa,
    -4px 4px 0 0 #f5f4fa, 0px 4px 0 0 #d99f6b, 4px 4px 0 0 #f5f4fa,
    /* body */
    -8px 8px 0 0 #d99f6b, -4px 8px 0 0 #d99f6b, 0px 8px 0 0 #d99f6b, 4px 8px 0 0 #d99f6b, 8px 8px 0 0 #d99f6b,
    -4px 12px 0 0 #a9754f, 4px 12px 0 0 #a9754f;
}

.pixel-bunny {
  box-shadow:
    /* ears */
    -6px -16px 0 0 #f5f4fa, 6px -16px 0 0 #f5f4fa,
    -6px -12px 0 0 #f0a3b8, 6px -12px 0 0 #f0a3b8,
    -6px -8px 0 0 #f5f4fa, 6px -8px 0 0 #f5f4fa,
    /* head */
    -8px -4px 0 0 #f5f4fa, -4px -4px 0 0 #f5f4fa, 0px -4px 0 0 #f5f4fa, 4px -4px 0 0 #f5f4fa, 8px -4px 0 0 #f5f4fa,
    -8px 0 0 0 #f5f4fa, -4px 0 0 0 #e87b7b, 0px 0 0 0 #f5f4fa, 4px 0 0 0 #e87b7b, 8px 0 0 0 #f5f4fa,
    /* nose */
    -8px 4px 0 0 #f5f4fa, -4px 4px 0 0 #f5f4fa, 0px 4px 0 0 #f0a3b8, 4px 4px 0 0 #f5f4fa, 8px 4px 0 0 #f5f4fa,
    /* body */
    -8px 8px 0 0 #f5f4fa, 0px 8px 0 0 #f5f4fa, 8px 8px 0 0 #f5f4fa,
    -4px 12px 0 0 #f5f4fa, 4px 12px 0 0 #f5f4fa;
}

.pet-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--color-text-main);
}

.pet-info {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-bottom: 16px;
}

.adopt-btn {
  width: 100%;
  padding: 10px 14px;
  background: var(--color-accent);
  color: #121019;
  font-size: 1rem;
  font-weight: 700;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

.adopt-btn:hover {
  background: var(--color-accent-hover);
}

.adopt-btn:active {
  transform: scale(0.97);
}

.adopt-btn:focus-visible {
  outline: var(--focus-ring);
  outline-offset: 2px;
}

.adopted-tag {
  display: inline-block;
  background: var(--color-success);
  color: #0d2915;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.empty-msg {
  color: var(--color-text-muted);
  font-style: italic;
  text-align: center;
  padding: 18px;
  background: rgba(0, 0, 0, 0.15);
  border-radius: 4px;
}

@media (max-width: 480px) {
  .shelter-container {
    padding: 20px 14px;
  }

  .shelter-title {
    font-size: 1.5rem;
  }

  .filter-buttons {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .pet-grid,
  .adopted-grid {
    grid-template-columns: 1fr;
  }
}

(function () {
  "use strict";

  var pets = [
    { id: 1, name: "Whiskers", species: "Cat", age: "2 yrs", adopted: false },
    { id: 2, name: "Pixel", species: "Dog", age: "1 yr", adopted: false },
    { id: 3, name: "Cotton", species: "Bunny", age: "6 mos", adopted: false },
    { id: 4, name: "Mochi", species: "Cat", age: "3 yrs", adopted: false },
    { id: 5, name: "Rusty", species: "Dog", age: "4 yrs", adopted: false },
    { id: 6, name: "Pip", species: "Bunny", age: "1 yr", adopted: false }
  ];

  var currentFilter = "all";

  var availableCountEl = document.getElementById("available-count");
  var adoptedCountEl = document.getElementById("adopted-count");
  var petsListEl = document.getElementById("pets-list");
  var adoptedListEl = document.getElementById("adopted-list");
  var noPetsMsgEl = document.getElementById("no-pets-msg");
  var noAdoptedMsgEl = document.getElementById("no-adopted-msg");
  var filterButtons = document.querySelectorAll(".filter-btn");

  function getSpriteClass(species) {
    switch (species.toLowerCase()) {
      case "cat":
        return "pixel-cat";
      case "dog":
        return "pixel-dog";
      case "bunny":
        return "pixel-bunny";
      default:
        return "pixel-cat";
    }
  }

  function createAvailablePetCard(pet) {
    var card = document.createElement("article");
    card.className = "pet-card";
    card.setAttribute("data-id", pet.id);

    var spriteBox = document.createElement("div");
    spriteBox.className = "sprite-box";
    spriteBox.setAttribute("aria-hidden", "true");

    var sprite = document.createElement("div");
    sprite.className = "pixel-sprite " + getSpriteClass(pet.species);
    spriteBox.appendChild(sprite);

    var nameEl = document.createElement("h3");
    nameEl.className = "pet-name";
    nameEl.textContent = pet.name;

    var infoEl = document.createElement("p");
    infoEl.className = "pet-info";
    infoEl.textContent = pet.species + " • " + pet.age;

    var adoptBtn = document.createElement("button");
    adoptBtn.type = "button";
    adoptBtn.className = "adopt-btn";
    adoptBtn.textContent = "Adopt " + pet.name;
    adoptBtn.setAttribute("aria-label", "Adopt " + pet.name + ", " + pet.species + ", " + pet.age);
    adoptBtn.addEventListener("click", function () {
      adoptPet(pet.id);
    });

    card.appendChild(spriteBox);
    card.appendChild(nameEl);
    card.appendChild(infoEl);
    card.appendChild(adoptBtn);

    return card;
  }

  function createAdoptedPetCard(pet) {
    var card = document.createElement("article");
    card.className = "pet-card adopted";
    card.setAttribute("data-id", pet.id);

    var spriteBox = document.createElement("div");
    spriteBox.className = "sprite-box";
    spriteBox.setAttribute("aria-hidden", "true");

    var sprite = document.createElement("div");
    sprite.className = "pixel-sprite " + getSpriteClass(pet.species);
    spriteBox.appendChild(sprite);

    var nameEl = document.createElement("h3");
    nameEl.className = "pet-name";
    nameEl.textContent = pet.name;

    var infoEl = document.createElement("p");
    infoEl.className = "pet-info";
    infoEl.textContent = pet.species + " • " + pet.age;

    var adoptedTag = document.createElement("span");
    adoptedTag.className = "adopted-tag";
    adoptedTag.textContent = "Adopted ❤️";

    card.appendChild(spriteBox);
    card.appendChild(nameEl);
    card.appendChild(infoEl);
    card.appendChild(adoptedTag);

    return card;
  }

  function adoptPet(petId) {
    for (var i = 0; i < pets.length; i++) {
      if (pets[i].id === petId) {
        pets[i].adopted = true;
        break;
      }
    }
    render();
  }

  function render() {
    var availablePets = pets.filter(function (pet) {
      return !pet.adopted;
    });
    var adoptedPets = pets.filter(function (pet) {
      return pet.adopted;
    });

    availableCountEl.textContent = String(availablePets.length);
    adoptedCountEl.textContent = String(adoptedPets.length);

    var filteredAvailable = availablePets.filter(function (pet) {
      if (currentFilter === "all") {
        return true;
      }
      return pet.species.toLowerCase() === currentFilter.toLowerCase();
    });

    petsListEl.innerHTML = "";
    if (filteredAvailable.length === 0) {
      noPetsMsgEl.removeAttribute("hidden");
    } else {
      noPetsMsgEl.setAttribute("hidden", "");
      filteredAvailable.forEach(function (pet) {
        petsListEl.appendChild(createAvailablePetCard(pet));
      });
    }

    adoptedListEl.innerHTML = "";
    if (adoptedPets.length === 0) {
      noAdoptedMsgEl.removeAttribute("hidden");
    } else {
      noAdoptedMsgEl.setAttribute("hidden", "");
      adoptedPets.forEach(function (pet) {
        adoptedListEl.appendChild(createAdoptedPetCard(pet));
      });
    }
  }

  filterButtons.forEach(function (button) {
    button.addEventListener("click", function () {
      filterButtons.forEach(function (btn) {
        btn.classList.remove("active");
        btn.setAttribute("aria-pressed", "false");
      });
      button.classList.add("active");
      button.setAttribute("aria-pressed", "true");
      currentFilter = button.getAttribute("data-species");
      render();
    });
  });

  render();
})();
